var comments = [];
try {
    comments = JSON.parse(msg.payload || '[]');
} catch (e) {
    node.error('Error parsing lead comments: ' + e.message);
}

var count = comments.filter(function(c) {
    return c.agent_id === 5 || c.role === 'lead_developer';
}).length;

var cmd = '';
if (count === 0) {
    var note = 'System Note: The Lead Engineer reviewed the task but failed to leave explicit instructions. Developer, please carefully review the previous failures and try again.';
    cmd = "build task update --id " + msg.task.id + " --status todo --agent-id 2 --comment-author-id 1 --comment \"" + note.replace(/"/g, "'") + "\" --audit-action assign_to_dev";
} else {
    cmd = "build task update --id " + msg.task.id + " --status todo --agent-id 2 --audit-action assign_to_dev";
}
msg.payload = cmd;
return msg;
